// ─────────────────────────────────────────────
//  product-textures.js
//  Estampas incrustadas en base64 (480x480, JPEG) para el visor 3D.
//  Se generan a partir de assets/products/*.jpg — evita que la textura WebGL
//  falle al abrir el sitio con doble clic (file://), donde el navegador no
//  puede validar el origen de una imagen cargada por ruta relativa.
//  Regenerar con sharp-cli si cambian las fotos: ver README de esta carpeta.
// ─────────────────────────────────────────────
